import{_ as t,o as r,c as a,a2 as s}from"./chunks/framework.C7GIOALF.js";const m=JSON.parse('{"title":"Marvel Sets and Supporting Card Pools","description":"","frontmatter":{},"headers":[],"relativePath":"research/marvel-card-pools.md","filePath":"research/marvel-card-pools.md","lastUpdated":null}'),o={name:"research/marvel-card-pools.md"};function n(d,e,l,c,i,h){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="marvel-sets-and-supporting-card-pools" tabindex="-1">Marvel Sets and Supporting Card Pools <a class="header-anchor" href="#marvel-sets-and-supporting-card-pools" aria-label="Permalink to &quot;Marvel Sets and Supporting Card Pools&quot;">​</a></h1><p><strong>Checked: October 19, 2026.</strong> This reference collects Marvel-branded Magic printings regardless of which product they came from, followed by other sets that could support Marvel-themed game-night boxes. It is a pool of possibilities, not a shopping list or a commitment to build one box from every set.</p><p>The released Marvel search currently reaches <strong>21 Scryfall set codes</strong>. That includes six principal card pools, nine promotional categories, three token sets, and three memorabilia categories. It does <strong>not</strong> mean there have been 21 separate Marvel expansions. Shared codes such as <code>SLD</code> contain much more than Marvel, and one retail release can use several codes.</p><h2 id="finding-marvel-cards-across-products" tabindex="-1">Finding Marvel cards across products <a class="header-anchor" href="#finding-marvel-cards-across-products" aria-label="Permalink to &quot;Finding Marvel cards across products&quot;">​</a></h2><p>Scryfall&#39;s working art tag is <strong><code>art:marvel-comics</code></strong>. This catches Marvel artwork on reprints as well as cards named after Marvel characters. It is more useful than searching only names or assuming every Marvel release has its own exclusive code. Art tags are community maintained, so a newly added printing can be missing a tag.</p><table tabindex="0"><thead><tr><th>Purpose</th><th>Search</th></tr></thead><tbody><tr><td>Browse Marvel cards for deck ideas</td><td><a href="https://scryfall.com/search?q=art%3Amarvel-comics" target="_blank" rel="noreferrer">Marvel artwork, one result per card</a></td></tr><tr><td>See alternate printings and art</td><td><a href="https://scryfall.com/search?q=art%3Amarvel-comics+unique%3Aprints" target="_blank" rel="noreferrer">Marvel artwork, every printing</a></td></tr><tr><td>Include tokens and other extras</td><td><a href="https://scryfall.com/search?q=art%3Amarvel-comics+unique%3Aprints+include%3Aextras" target="_blank" rel="noreferrer">Marvel artwork with extras and all printings</a></td></tr><tr><td>Reproduce this released-only snapshot</td><td><a href="https://scryfall.com/search?q=art%3Amarvel-comics+unique%3Aprints+include%3Aextras+date%3C%3D2026-10-19" target="_blank" rel="noreferrer">Marvel printings dated on or before October 19, 2026</a></td></tr><tr><td>Find Marvel Secret Lair cards without unrelated drops</td><td><a href="https://scryfall.com/search?q=set%3Asld+art%3Amarvel-comics" target="_blank" rel="noreferrer">Marvel artwork in SLD</a></td></tr></tbody></table><p>The broad queries without a date cutoff can include previews. <code>unique:prints</code> intentionally repeats cards with different printings; omit it when choosing distinct cards for a singleton pool. <code>include:extras</code> exposes objects such as tokens and art cards that are not ordinary deck cards.</p><h2 id="principal-released-marvel-card-pools" tabindex="-1">Principal released Marvel card pools <a class="header-anchor" href="#principal-released-marvel-card-pools" aria-label="Permalink to &quot;Principal released Marvel card pools&quot;">​</a></h2><p>The names below are Scryfall&#39;s exact set names. Set links open the whole category; use the Marvel art tag when a category also contains unrelated material.</p><table tabindex="0"><thead><tr><th>Code</th><th>Set name</th><th>Why it belongs in the search</th></tr></thead><tbody><tr><td><code>SPM</code></td><td><a href="https://scryfall.com/sets/spm" target="_blank" rel="noreferrer">Marvel&#39;s Spider-Man</a></td><td>Main Spider-Man expansion, released September 26, 2025.</td></tr><tr><td><code>SPE</code></td><td><a href="https://scryfall.com/sets/spe" target="_blank" rel="noreferrer">Marvel&#39;s Spider-Man Eternal</a></td><td>Supplemental Spider-Man cards under a separate code, also September 26, 2025. Searching only SPM misses this pool.</td></tr><tr><td><code>MSH</code></td><td><a href="https://scryfall.com/sets/msh" target="_blank" rel="noreferrer">Marvel Super Heroes</a></td><td>Main Marvel expansion, released June 26, 2026.</td></tr><tr><td><code>MSC</code></td><td><a href="https://scryfall.com/sets/msc" target="_blank" rel="noreferrer">Marvel Super Heroes Commander</a></td><td>Includes the Marvel Commander and <strong>Jumpstart</strong> card pool. The name does not mean every MSC card came from a Commander deck. Released June 26, 2026.</td></tr><tr><td><code>MAR</code></td><td><a href="https://scryfall.com/sets/mar" target="_blank" rel="noreferrer">Marvel Universe</a></td><td>Marvel Source Material reprints, including material associated with different Marvel releases. The category began September 26, 2025.</td></tr><tr><td><code>SLD</code></td><td><a href="https://scryfall.com/search?q=set%3Asld+art%3Amarvel-comics" target="_blank" rel="noreferrer">Secret Lair Drop</a></td><td>The shared Secret Lair category contains the early Marvel character drops and later Marvel releases. Filter it by Marvel artwork.</td></tr></tbody></table><p>Wizards&#39; <a href="https://magic.wizards.com/en/news/announcements/marvel-super-heroes-jumpstart-booster-themes" target="_blank" rel="noreferrer">Marvel Jumpstart themes and decklists</a> explicitly identify new Jumpstart cards with <strong>MSC</strong>. The <a href="https://magic.wizards.com/en/news/feature/collecting-marvel-super-heroes" target="_blank" rel="noreferrer">Marvel collecting guide</a> is the companion product reference.</p><p>The first <a href="https://magic.wizards.com/en/news/announcements/secret-lair-marvel-superdrop" target="_blank" rel="noreferrer">Marvel Secret Lair Superdrop</a> went on sale <strong>November 4, 2024</strong>, before the Spider-Man expansion. It consisted of five character drops: Black Panther, Captain America, Iron Man, Wolverine, and Storm. Those drops share SLD; they are not five separate Scryfall set codes. The date of the overall SLD category is not the release date of its Marvel cards.</p><p>To browse the main dedicated pools plus Marvel Secret Lair cards, use:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(set:spm or set:spe or set:msh or set:msc or set:mar or (set:sld art:marvel-comics))</span></span></code></pre></div><p>That is a practical deck-building search, not the complete promotional and memorabilia inventory below.</p><h2 id="promotional-printings" tabindex="-1">Promotional printings <a class="header-anchor" href="#promotional-printings" aria-label="Permalink to &quot;Promotional printings&quot;">​</a></h2><p>Each category below contained at least one Marvel-tagged printing in the released snapshot. Most are shared promotional categories, so the links apply the Marvel filter. They are chiefly relevant when choosing artwork or tracking every version, rather than finding an entirely new expansion&#39;s worth of cards.</p><table tabindex="0"><thead><tr><th>Code</th><th>Exact set name</th><th>Marvel-filtered browse</th></tr></thead><tbody><tr><td><code>PSPM</code></td><td>Marvel&#39;s Spider-Man Promos</td><td><a href="https://scryfall.com/search?q=set%3Apspm+art%3Amarvel-comics+unique%3Aprints" target="_blank" rel="noreferrer">Cards</a></td></tr><tr><td><code>LMAR</code></td><td>Marvel Legends Series Inserts</td><td><a href="https://scryfall.com/search?q=set%3Almar+art%3Amarvel-comics+unique%3Aprints" target="_blank" rel="noreferrer">Cards</a></td></tr><tr><td><code>PMEI</code></td><td>Media and Collaboration Promos</td><td><a href="https://scryfall.com/search?q=set%3Apmei+art%3Amarvel-comics+unique%3Aprints" target="_blank" rel="noreferrer">Cards</a></td></tr><tr><td><code>PURL</code></td><td>URL/Convention Promos</td><td><a href="https://scryfall.com/search?q=set%3Apurl+art%3Amarvel-comics+unique%3Aprints" target="_blank" rel="noreferrer">Cards</a></td></tr><tr><td><code>PW25</code></td><td>Wizards Play Network 2025</td><td><a href="https://scryfall.com/search?q=set%3Apw25+art%3Amarvel-comics+unique%3Aprints" target="_blank" rel="noreferrer">Cards</a></td></tr><tr><td><code>PW26</code></td><td>Wizards Play Network 2026</td><td><a href="https://scryfall.com/search?q=set%3Apw26+art%3Amarvel-comics+unique%3Aprints" target="_blank" rel="noreferrer">Cards</a></td></tr><tr><td><code>PSPL</code></td><td>Spotlight Series</td><td><a href="https://scryfall.com/search?q=set%3Apspl+art%3Amarvel-comics+unique%3Aprints" target="_blank" rel="noreferrer">Cards</a></td></tr><tr><td><code>PF25</code></td><td>MagicFest 2025</td><td><a href="https://scryfall.com/search?q=set%3Apf25+art%3Amarvel-comics+unique%3Aprints" target="_blank" rel="noreferrer">Cards</a></td></tr><tr><td><code>PPRO</code></td><td>Pro Tour Promos</td><td><a href="https://scryfall.com/search?q=set%3Appro+art%3Amarvel-comics+unique%3Aprints" target="_blank" rel="noreferrer">Cards</a></td></tr></tbody></table><p>The date assigned to an annual promo category or its records is not necessarily the day that a particular promotional copy became obtainable. These are Scryfall catalogue categories, not an assertion that every insert has the same physical form or tournament status.</p><h2 id="tokens-and-memorabilia" tabindex="-1">Tokens and memorabilia <a class="header-anchor" href="#tokens-and-memorabilia" aria-label="Permalink to &quot;Tokens and memorabilia&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Exact set name</th><th>Use in a box</th></tr></thead><tbody><tr><td><code>TSPM</code></td><td><a href="https://scryfall.com/sets/tspm" target="_blank" rel="noreferrer">Marvel&#39;s Spider-Man Tokens</a></td><td>Token components, including the 1/1 flying Robot.</td></tr><tr><td><code>TMSH</code></td><td><a href="https://scryfall.com/sets/tmsh" target="_blank" rel="noreferrer">Marvel Super Heroes Tokens</a></td><td>Token components for the main Marvel release.</td></tr><tr><td><code>TMSC</code></td><td><a href="https://scryfall.com/sets/tmsc" target="_blank" rel="noreferrer">Marvel Super Heroes Commander Tokens</a></td><td>Token components associated with MSC.</td></tr><tr><td><code>ASPM</code></td><td><a href="https://scryfall.com/sets/aspm" target="_blank" rel="noreferrer">Marvel&#39;s Spider-Man Art Series</a></td><td>Art cards, not ordinary playable Magic cards. Potential decorative dividers.</td></tr><tr><td><code>AMSH</code></td><td><a href="https://scryfall.com/sets/amsh" target="_blank" rel="noreferrer">Marvel Super Heroes Art Series</a></td><td>Art cards, likewise separate from the playable pool.</td></tr><tr><td><code>FMSC</code></td><td><a href="https://scryfall.com/sets/fmsc" target="_blank" rel="noreferrer">Marvel Super Heroes Jumpstart Front Cards</a></td><td>Jumpstart theme/front cards. Useful packet identifiers, not cards in the forty-card playing deck.</td></tr></tbody></table><p>Tokens can be physical components of a Horde under its selected rules. That does not turn a token into an ordinary deck card in every format.</p><h2 id="previewed-or-scheduled-material" tabindex="-1">Previewed or scheduled material <a class="header-anchor" href="#previewed-or-scheduled-material" aria-label="Permalink to &quot;Previewed or scheduled material&quot;">​</a></h2><p>These were already represented in Scryfall on the research date, but fall <strong>after</strong> the October 19, 2026 cutoff and are excluded from the 21 released codes above. Dates are the catalogue&#39;s current schedule and may change.</p><table tabindex="0"><thead><tr><th>Code</th><th>Exact set name</th><th>Date shown for the relevant material</th></tr></thead><tbody><tr><td><code>SLC</code></td><td><a href="https://scryfall.com/search?q=set%3Aslc+art%3Amarvel-comics" target="_blank" rel="noreferrer">Secret Lair Countdown — Marvel-filtered cards</a></td><td>Marvel printings dated November 2, 2026. SLC is a shared category whose older start date is not the date of these Marvel printings.</td></tr><tr><td><code>MDD</code></td><td><a href="https://scryfall.com/sets/mdd" target="_blank" rel="noreferrer">Marvel: Darkhold Destiny</a></td><td>April 9, 2027.</td></tr><tr><td><code>MDC</code></td><td><a href="https://scryfall.com/sets/mdc" target="_blank" rel="noreferrer">Darkhold Destiny Commander</a></td><td>April 9, 2027.</td></tr><tr><td><code>TMDD</code></td><td><a href="https://scryfall.com/sets/tmdd" target="_blank" rel="noreferrer">Marvel: Darkhold Destiny Tokens</a></td><td>April 9, 2027.</td></tr></tbody></table><h2 id="other-sets-that-can-support-marvel-themes" tabindex="-1">Other sets that can support Marvel themes <a class="header-anchor" href="#other-sets-that-can-support-marvel-themes" aria-label="Permalink to &quot;Other sets that can support Marvel themes&quot;">​</a></h2><p>These are thematic suggestions. A setting can offer useful supporting cards without needing its own dedicated crossover box. In particular, Teenage Mutant Ninja Turtles and Transformers can supply occasional guests in a broader Marvel game.</p><h3 id="superheroes-city-life-and-crossover-guests" tabindex="-1">Superheroes, city life, and crossover guests <a class="header-anchor" href="#superheroes-city-life-and-crossover-guests" aria-label="Permalink to &quot;Superheroes, city life, and crossover guests&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Codes and exact names</th><th>Useful material</th><th>Fit to check</th></tr></thead><tbody><tr><td><code>TMT</code> <a href="https://scryfall.com/sets/tmt" target="_blank" rel="noreferrer">Teenage Mutant Ninja Turtles</a>; <code>TMC</code> <a href="https://scryfall.com/sets/tmc" target="_blank" rel="noreferrer">Teenage Mutant Ninja Turtles Eternal</a>; <code>PZA</code> <a href="https://scryfall.com/sets/pza" target="_blank" rel="noreferrer">Teenage Mutant Ninja Turtles Source Material</a></td><td>Other comic-book heroes, New York, street life, pizza, ninjas, and machines. <code>TTMT</code> <a href="https://scryfall.com/sets/ttmt" target="_blank" rel="noreferrer">Teenage Mutant Ninja Turtles Tokens</a> supplies tokens.</td><td>Named turtles and mutants are explicit crossover guests. Ordinary city props can blend more quietly.</td></tr><tr><td><code>BOT</code> <a href="https://scryfall.com/sets/bot" target="_blank" rel="noreferrer">Transformers</a></td><td>Named robot heroes and villains, often with vehicle faces.</td><td>BOT is its own code even though the cards appeared alongside The Brothers&#39; War. Named Autobots/Decepticons are not anonymous Ultron drones.</td></tr><tr><td><code>SNC</code> <a href="https://scryfall.com/sets/snc" target="_blank" rel="noreferrer">Streets of New Capenna</a>; <code>NCC</code> <a href="https://scryfall.com/sets/ncc" target="_blank" rel="noreferrer">New Capenna Commander</a></td><td>Urban streets, citizens, organized crime, businesses, and vehicles.</td><td>Art Deco fantasy city; many inhabitants and objects are supernatural. Select individually for an ordinary modern-city joke.</td></tr><tr><td><code>MKM</code> <a href="https://scryfall.com/sets/mkm" target="_blank" rel="noreferrer">Murders at Karlov Manor</a>; <code>MKC</code> <a href="https://scryfall.com/sets/mkc" target="_blank" rel="noreferrer">Murders at Karlov Manor Commander</a></td><td>Detectives, witnesses, evidence, and everyday objects.</td><td>Ravnica is a fantasy city. Investigators may be nonhuman or magical even when their jobs sound ordinary.</td></tr><tr><td><code>NEO</code> <a href="https://scryfall.com/sets/neo" target="_blank" rel="noreferrer">Kamigawa: Neon Dynasty</a>; <code>NEC</code> <a href="https://scryfall.com/sets/nec" target="_blank" rel="noreferrer">Neon Dynasty Commander</a></td><td>Futuristic urban technology, vehicles, and machines.</td><td>Neon city imagery can fit a technological Marvel box; spirits, cybernetics, and samurai are more specific departures.</td></tr><tr><td><code>PIP</code> <a href="https://scryfall.com/sets/pip" target="_blank" rel="noreferrer">Fallout</a>; <code>TPIP</code> <a href="https://scryfall.com/sets/tpip" target="_blank" rel="noreferrer">Fallout Tokens</a></td><td>Actual Robot creatures, appliances, supplies, and retro technology.</td><td>A post-apocalyptic franchise with recognizable robot models. A useful machine source, but not franchise-neutral by default.</td></tr></tbody></table><p>See the separate <a href="./everyday-life.html">everyday-life catalogue</a> for individual mundane cards and clearly marked almost matches.</p><h3 id="generic-machine-sources" tabindex="-1">Generic machine sources <a class="header-anchor" href="#generic-machine-sources" aria-label="Permalink to &quot;Generic machine sources&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Codes and exact names</th><th>What to browse</th><th>Visual character</th></tr></thead><tbody><tr><td><code>KLD</code> <a href="https://scryfall.com/sets/kld" target="_blank" rel="noreferrer">Kaladesh</a>; <code>AER</code> <a href="https://scryfall.com/sets/aer" target="_blank" rel="noreferrer">Aether Revolt</a></td><td>Constructs, Servos, Thopters, inventors, and artifact support. Tokens: <code>TKLD</code> <a href="https://scryfall.com/sets/tkld" target="_blank" rel="noreferrer">Kaladesh Tokens</a>, <code>TAER</code> <a href="https://scryfall.com/sets/taer" target="_blank" rel="noreferrer">Aether Revolt Tokens</a>.</td><td>Ornate industrial inventions; often easier to cast as an inventor&#39;s machines than a spacecraft crew.</td></tr><tr><td><code>NEO</code> <a href="https://scryfall.com/sets/neo" target="_blank" rel="noreferrer">Kamigawa: Neon Dynasty</a></td><td>Small artifact creatures such as <a href="https://scryfall.com/card/neo/254/patchwork-automaton" target="_blank" rel="noreferrer">Patchwork Automaton</a> and <a href="https://scryfall.com/card/neo/248/iron-apprentice" target="_blank" rel="noreferrer">Iron Apprentice</a>. Tokens: <code>TNEO</code> <a href="https://scryfall.com/sets/tneo" target="_blank" rel="noreferrer">Kamigawa: Neon Dynasty Tokens</a>.</td><td>Futuristic machines in an urban setting. Both named examples are Constructs.</td></tr><tr><td><code>MRD</code> <a href="https://scryfall.com/sets/mrd" target="_blank" rel="noreferrer">Mirrodin</a>; <code>SOM</code> <a href="https://scryfall.com/sets/som" target="_blank" rel="noreferrer">Scars of Mirrodin</a>; <code>MBS</code> <a href="https://scryfall.com/sets/mbs" target="_blank" rel="noreferrer">Mirrodin Besieged</a></td><td>Myr, Constructs, artifact creatures, and mechanical armies.</td><td>A metallic fantasy world. Useful machine silhouettes, but some cards are visibly alien or Phyrexian.</td></tr><tr><td><code>EOE</code> <a href="https://scryfall.com/sets/eoe" target="_blank" rel="noreferrer">Edge of Eternities</a>; <code>EOC</code> <a href="https://scryfall.com/sets/eoc" target="_blank" rel="noreferrer">Edge of Eternities Commander</a></td><td>Robots and artifact support already used in the owner&#39;s earlier robot Creature Feature deck. Tokens: <code>TEOE</code> <a href="https://scryfall.com/sets/teoe" target="_blank" rel="noreferrer">Edge of Eternities Tokens</a>.</td><td>Explicit space imagery. Good for cosmic Marvel; individual art may feel less grounded in New York.</td></tr></tbody></table><p>For machines across Magic&#39;s own settings, try:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(t:robot or t:construct or t:myr or t:servo or t:thopter) t:creature -is:ub</span></span></code></pre></div><p><a href="https://scryfall.com/search?q=%28t%3Arobot+or+t%3Aconstruct+or+t%3Amyr+or+t%3Aservo+or+t%3Athopter%29+t%3Acreature+-is%3Aub" target="_blank" rel="noreferrer">Open the machine search</a>. This is a discovery query, not a list of cards with the Robot type or a pre-approved Horde list.</p><h3 id="actual-robot-tokens" tabindex="-1">Actual Robot tokens <a class="header-anchor" href="#actual-robot-tokens" aria-label="Permalink to &quot;Actual Robot tokens&quot;">​</a></h3><p>A token named <strong>Robot</strong> exists in several sizes. Pick the token profile the box&#39;s rules actually call for; these are not interchangeable rules objects.</p><table tabindex="0"><thead><tr><th>Printing</th><th>Characteristics</th><th>Theme consideration</th></tr></thead><tbody><tr><td><a href="https://scryfall.com/card/ttmt/10/robot" target="_blank" rel="noreferrer">TTMT 10 — Robot</a></td><td>1/1 colorless artifact creature — Robot; no abilities.</td><td>TMNT artwork.</td></tr><tr><td><a href="https://scryfall.com/card/tspm/6/robot" target="_blank" rel="noreferrer">TSPM 6 — Robot</a></td><td>1/1 colorless artifact creature — Robot with flying.</td><td>Spider-Man artwork; flying changes the Horde&#39;s combat.</td></tr><tr><td><a href="https://scryfall.com/card/teoe/10/robot" target="_blank" rel="noreferrer">TEOE 10 — Robot</a></td><td>2/2 colorless artifact creature — Robot; no abilities.</td><td>The existing space-themed option.</td></tr><tr><td><a href="https://scryfall.com/card/tpip/16/robot" target="_blank" rel="noreferrer">TPIP 16 — Robot</a></td><td>3/3 colorless artifact creature — Robot; no abilities.</td><td>Fallout artwork; a simple rules profile.</td></tr><tr><td><a href="https://scryfall.com/card/t40k/23/robot" target="_blank" rel="noreferrer">T40K 23 — Robot</a></td><td>4/4 colorless artifact creature — Robot; cannot block.</td><td>Warhammer 40,000 artwork and a distinct restriction.</td></tr></tbody></table><p><a href="https://scryfall.com/search?q=%21%22Robot%22+t%3Atoken+include%3Aextras+unique%3Aprints" target="_blank" rel="noreferrer">Browse every Robot token printing</a>. Cards named Servo or Thopter can also look robotic, but they have their own types and characteristics.</p><h2 id="using-this-research-in-boxes" tabindex="-1">Using this research in boxes <a class="header-anchor" href="#using-this-research-in-boxes" aria-label="Permalink to &quot;Using this research in boxes&quot;">​</a></h2><p><strong>Choose the game rules first, then build a thematic card pool that follows them.</strong> Creature Feature counts actual creature types: Robot, Construct, Myr, Servo, and Thopter are not synonyms. A supporting creature that looks like a robot does not automatically meet a Robot requirement. See the <a href="./../formats/creature-feature/rules.html">complete Creature Feature rules</a>.</p><p>A Horde can mix mechanical-looking creature types when its selected rules allow it. Check targeting, optional abilities, repeated activations, and infinite-mana interactions before adding complex cards. Any special automation procedure belongs explicitly in that box&#39;s rules. Do not assume a thematic card can run itself.</p><p>For an Age of Ultron idea, anonymous machines can be more coherent than importing another villain&#39;s distinctive army. The verified card <a href="https://scryfall.com/card/msc/507/ultron-machine-overlord" target="_blank" rel="noreferrer">Ultron, Machine Overlord</a> is a Robot Villain and gives other Robots and Constructs +2/+2. That is a specific card option, not a requirement to buy Ultron or make every Marvel card fit that box.</p><p>The project&#39;s preference is variety and usually one copy of each nonbasic card, with duplicates justified by a real play requirement. A themed box need not consume every spare card. Several smaller boxes, a singleton cube, and reusable <a href="./../formats/jumpstart/building-packets.html">Jumpstart packets</a> can use different parts of these pools.</p><h2 id="sources-and-maintenance" tabindex="-1">Sources and maintenance <a class="header-anchor" href="#sources-and-maintenance" aria-label="Permalink to &quot;Sources and maintenance&quot;">​</a></h2><ul><li>Set names and codes: <a href="https://scryfall.com/sets" target="_blank" rel="noreferrer">Scryfall set directory</a> and <a href="https://api.scryfall.com/sets" target="_blank" rel="noreferrer">set metadata API</a>, checked October 19, 2026.</li><li>Card names, types, token profiles, and searches: Scryfall, queried through the project&#39;s <a href="https://github.com/cryppadotta/scryfall-mcp" target="_blank" rel="noreferrer">Scryfall MCP server</a>.</li><li>Product context: Wizards&#39; <a href="https://magic.wizards.com/en/news/announcements/secret-lair-marvel-superdrop" target="_blank" rel="noreferrer">2024 Marvel Secret Lair announcement</a>, <a href="https://magic.wizards.com/en/news/feature/collecting-marvel-super-heroes" target="_blank" rel="noreferrer">Marvel collecting guide</a>, and <a href="https://magic.wizards.com/en/news/announcements/marvel-super-heroes-jumpstart-booster-themes" target="_blank" rel="noreferrer">Marvel Jumpstart themes</a>.</li></ul><p>The 21-code inventory was obtained by searching <code>art:marvel-comics date&lt;=2026-10-19 include:extras unique:prints</code>, then excluding already found set codes until no results remained. A cross-check of the dedicated SPM, SPE, MSH, MSC, and MAR pools found no released cards missing that art tag at the time. This is a dated best-effort catalogue, not a promise that future printings will be tagged immediately.</p><p>When updating it, repeat the unrestricted Marvel-art search, inspect new set codes, check individual printing dates in shared promotional/Secret Lair categories, and keep upcoming material separate from released cards. Preserve this distinction rather than treating a set category&#39;s start date as every card&#39;s release date.</p>',48)])])}const f=t(o,[["render",n]]);export{m as __pageData,f as default};
